"""Crash inside append_event after the event body is durable and before its newline, then retry."""
import os, json, tempfile
from pathlib import Path
from orch import journal

def ev(run, seq):
    return {
        "$schema": "urn:swissknifeman:orch:exec:run-event:v1", "contract_version": "exec/v1",
        "run_id": run, "stage_id": "primary", "attempt": 1, "seq": seq,
        "ts": f"2026-10-05T17:00:{seq:02d}Z", "kind": "output", "event_id": f"evt-{seq}",
    }

with tempfile.TemporaryDirectory() as tmp:
    env = {"SKM_HOME": str(Path(tmp) / "skm")}
    run = "run-newline"
    directory = journal.run_dir(run, env=env)
    journal.append_event(directory, ev(run, 1))
    path = directory / "events.jsonl"
    real = os.write
    armed = {"on": True}
    def crash_before_newline(fd, data):
        if not armed["on"]:
            return real(fd, data)
        try:
            name = os.readlink(f"/proc/self/fd/{fd}")
        except OSError:
            name = ""
        blob = bytes(data)
        if name.endswith("events.jsonl") and blob.endswith(b"\n") and b"\n" not in blob[:-1]:
            real(fd, blob[:-1])
            armed["on"] = False
            raise OSError(5, "crash before trailing newline")
        return real(fd, data)
    os.write = crash_before_newline
    try:
        journal.append_event(directory, ev(run, 2))
        raise SystemExit("append did not crash")
    except OSError as exc:
        print("first append:", exc)
    finally:
        os.write = real
    print("readable seqs after crash:", [doc["seq"] for doc in journal.read_events(directory)])
    print("retry returned:", journal.append_event(directory, ev(run, 2)))
    seqs = [doc["seq"] for doc in journal.read_events(directory)]
    print("readable seqs after retry:", seqs, "copies of seq 2:", seqs.count(2))
    print(path.read_text())
